// JWT Validation for Status Check
const webhookData = $json;
const headers = webhookData.headers || {};
const params = webhookData.params || {};

// Extract JWT token
const authHeader = headers.authorization || headers.Authorization || '';
const token = authHeader.replace(/^Bearer\s+/i, '').trim();

if (!token) {
  throw new Error('UNAUTHORIZED: Missing authorization token');
}

// Decode JWT
try {
  const parts = token.split('.');
  if (parts.length !== 3) {
    throw new Error('Invalid JWT format');
  }

  const payload = JSON.parse(
    Buffer.from(parts[1].replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString()
  );

  const userId = payload.sub;
  const userEmail = payload.email;

  if (!userId) {
    throw new Error('Invalid token: missing user ID');
  }

  // Get job ID from URL params
  const jobId = params.jobId;

  if (!jobId) {
    throw new Error('Missing job ID in request');
  }

  console.log('✅ Status check request');
  console.log('   User:', userEmail);
  console.log('   Job ID:', jobId);

  return [{
    json: {
      userId: userId,
      userEmail: userEmail,
      jobId: jobId,
      requestTimestamp: new Date().toISOString()
    }
  }];

} catch (error) {
  throw new Error('UNAUTHORIZED: Invalid JWT token - ' + error.message);
}

