// Format Job Status Response
const job = $json[0]; // Supabase returns array

// Calculate processing time if completed
let processingTime = null;
if (job.started_at && job.completed_at) {
  const start = new Date(job.started_at);
  const end = new Date(job.completed_at);
  processingTime = Math.round((end - start) / 1000); // seconds
}

// Estimate time remaining (rough estimate)
let estimatedTimeRemaining = null;
if (job.status !== 'completed' && job.status !== 'failed') {
  const elapsed = job.started_at ? 
    Math.round((new Date() - new Date(job.started_at)) / 1000) : 0;
  const totalEstimate = job.duration * 4; // Rough: 4 seconds per video second
  estimatedTimeRemaining = Math.max(0, totalEstimate - elapsed);
}

const output = {
  success: true,
  jobId: job.job_id,

  // Status
  status: job.status,
  progress: job.progress_percentage,
  currentStep: job.current_step,

  // Product info
  productName: job.product_name,
  ugcType: job.ugc_type,
  targetAudience: job.target_audience,

  // Video specs
  duration: job.duration,
  totalScenes: job.total_scenes,
  aspectRatio: job.aspect_ratio,
  platform: job.platform,

  // Results (only if completed)
  videoUrl: job.video_url || null,
  thumbnailUrl: job.thumbnail_url || null,

  // Error (only if failed)
  error: job.error_message || null,

  // Timing
  createdAt: job.created_at,
  startedAt: job.started_at,
  completedAt: job.completed_at,
  processingTimeSeconds: processingTime,
  estimatedTimeRemaining: estimatedTimeRemaining,

  // Credits
  creditsCharged: job.credits_cost,
  creditsRefunded: job.credits_refunded || 0,

  // Metadata
  category: job.product_category,
  character: job.character_model ? {
    age: job.character_model.age,
    gender: job.character_model.gender,
    style: job.character_model.style
  } : null
};

console.log('✅ Job status:', job.status, '-', job.progress_percentage + '%');

return [{ json: output }];
